import re
from datetime import datetime

_DISPLAY_NAME_RE = re.compile(r"<([^<>]*)>")
_PHONE_EXT_RE = re.compile(r"ext|x|#", re.IGNORECASE)
_ZIP_PLUS4_RE = re.compile(r"[0-9]{5}-[0-9]{4}")
_ZIP4_RE = re.compile(r"[0-9]{4}")
_ZIP5_RE = re.compile(r"[0-9]{5}")
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}
_TAG_SPLIT_RE = re.compile(r"[;,]")


def _normalize_email(raw):
    s = raw
    m = _DISPLAY_NAME_RE.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.replace(".", "").split("+", 1)[0]
            s = local + "@gmail.com"
    return s


def _is_valid_email(s):
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    return (bool(local) and "." in domain
            and not domain.startswith(".") and not domain.endswith("."))


def _normalize_phone(raw):
    m = _PHONE_EXT_RE.search(raw)
    if m:
        raw = raw[:m.start()]
    digits = "".join(c for c in raw if "0" <= c <= "9")
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _is_valid_phone(digits):
    return len(digits) == 10 and digits[0] not in "01"


def _normalize_zip(raw):
    z = raw.strip()
    if _ZIP_PLUS4_RE.fullmatch(z):
        z = z.split("-", 1)[0]
    if _ZIP4_RE.fullmatch(z):
        z = "0" + z
    return z if _ZIP5_RE.fullmatch(z) else ""


def _normalize_name(raw):
    s = raw.strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def _normalize_tags(raw):
    return {t.strip().lower() for t in _TAG_SPLIT_RE.split(raw) if t.strip()}


def _pick(members, field):
    """Pick the normalized value of `field` from the group's members.
    Prefers manual rows, then most recent `updated`, then earliest input row.
    Members are in input order, and sorts are stable."""
    cands = [m for m in members if m[field]]
    if not cands:
        return ""
    cands.sort(key=lambda m: m["updated"], reverse=True)  # ties keep input order
    cands.sort(key=lambda m: not m["manual"])             # manual first, stable
    return cands[0][field]


def dedupe_contacts(rows):
    # Normalize rows and drop any without a valid email or phone.
    kept = []
    for row in rows:
        email = _normalize_email(row.get("email", ""))
        if not _is_valid_email(email):
            email = ""
        phone = _normalize_phone(row.get("phone", ""))
        if not _is_valid_phone(phone):
            phone = ""
        if not email and not phone:
            continue

        source = row.get("source", "").strip().lower()
        kept.append({
            "first_name": _normalize_name(row.get("first_name", "")),
            "last_name": _normalize_name(row.get("last_name", "")),
            "zip": _normalize_zip(row.get("zip", "")),
            "email": email,
            "phone": phone,
            "source": source,
            "manual": source == "manual",
            "tags": _normalize_tags(row.get("tags", "")),
            "opted_out": row.get("opted_out", "").strip().lower() in _OPT_OUT_VALUES,
            "updated": _parse_updated(row["updated"]),
        })

    # Union-find over positions in `kept` (which preserves input order).
    parent = list(range(len(kept)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    email_seen = {}
    phone_seen = {}
    for pos, rec in enumerate(kept):
        if rec["email"]:
            if rec["email"] in email_seen:
                union(pos, email_seen[rec["email"]])
            else:
                email_seen[rec["email"]] = pos
        if rec["phone"] and rec["last_name"]:
            key = (rec["phone"], rec["last_name"].casefold())
            if key in phone_seen:
                union(pos, phone_seen[key])
            else:
                phone_seen[key] = pos

    # Group positions by root; groups are ordered by earliest input row.
    groups = {}
    order = []
    for pos in range(len(kept)):
        root = find(pos)
        if root not in groups:
            groups[root] = []
            order.append(root)
        groups[root].append(pos)

    # Build one output record per person.
    result = []
    for root in order:
        members = [kept[p] for p in groups[root]]
        all_tags = set()
        for m in members:
            all_tags |= m["tags"]
        result.append({
            "first_name": _pick(members, "first_name"),
            "last_name": _pick(members, "last_name"),
            "zip": _pick(members, "zip"),
            "email": _pick(members, "email"),
            "phone": _pick(members, "phone"),
            "source": _pick(members, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": "Y" if any(m["opted_out"] for m in members) else "N",
            "updated": max(m["updated"] for m in members).strftime("%Y-%m-%d"),
        })
    return result
